      STOP_AGENT: "agent:stop",
      /** 单独停止一个子代理 */
      STOP_SUBAGENT: "agent:stop-subagent",
      /** 用户插话给运行中的子代理 */
      STEER_SUBAGENT: "agent:steer-subagent",
      /** 自动选择模型：分类服务状态与模型池信息（设置卡片用） */
      GET_MODEL_ROUTING_INFO: "agent:get-model-routing-info",
      /** 自动选择模型：预热分类服务（主进程节流） */
      WARM_MODEL_ROUTER: "agent:warm-model-router",
      /** 设置里手动恢复一个被暂时绕开的模型 */
      RESUME_ROUTE_MODEL: "agent:resume-route-model",
      /** 自动选择模型：设置里的「试一试」（规则先在本机检查） */
      PREVIEW_ROUTE_CATEGORY: "agent:preview-route-category",
      /** 自动选择模型：输入框开关会话的规则类别（null 关闭） */
      SET_SESSION_ROUTE_CATEGORY: "agent:set-session-route-category",
      /** 对话菜单「使用记忆」：true 表示这个对话不使用记忆 */
      SET_SESSION_MEMORY_OFF: "agent:set-session-memory-off",
      // 后台任务管理
      // 工作区能力（MCP + Skill）
      /** 获取工作区能力摘要 */
      GET_CAPABILITIES: "agent:get-capabilities",
      /** 获取工作区 MCP 配置 */
      GET_MCP_CONFIG: "agent:get-mcp-config",
      GET_MCP_CATALOG: "agent:get-mcp-catalog",
      INSTALL_MCP: "agent:install-mcp",
      /** 保存工作区 MCP 配置 */
      SAVE_MCP_CONFIG: "agent:save-mcp-config",
      /** 测试 MCP 服务器连接 */
      TEST_MCP_SERVER: "agent:test-mcp-server",
      /** 获取工作区 Skill 列表 */
      GET_SKILLS: "agent:get-skills",
      GET_SKILL_PACKAGES: "agent:get-skill-packages",
      GET_SKILL_GROUP_ORDER: "agent:get-skill-group-order",
      MOVE_SKILL_GROUP: "agent:move-skill-group",
      CHECK_DOCUMENT_PYTHON: "agent:check-document-python",
      /** 托管技能运行时：状态、安装或更新（设置页与首次引导用） */
      GET_SKILL_ENV_STATUS: "agent:get-skill-env-status",
      INSTALL_SKILL_ENV_PACKAGES: "agent:install-skill-env-packages",
      IMPORT_SKILL_PACKAGE: "agent:import-skill-package",
      MANAGE_SKILL_PACKAGE: "agent:manage-skill-package",
      /** 自定义子代理类型：列表、读取、保存、删除、启用/停用 */
      LIST_SUBAGENT_TYPES: "agent:list-subagent-types",
      GET_SUBAGENT_TYPE: "agent:get-subagent-type",
      SAVE_SUBAGENT_TYPE: "agent:save-subagent-type",
      DELETE_SUBAGENT_TYPE: "agent:delete-subagent-type",
      TOGGLE_SUBAGENT_TYPE: "agent:toggle-subagent-type",
      /** 获取工作区 Skills 目录绝对路径 */
      GET_SKILLS_DIR: "agent:get-skills-dir",
      /** 删除工作区 Skill */
      DELETE_SKILL: "agent:delete-skill",
      /** 切换工作区 Skill 启用/禁用 */
